export function step(creature) {
  const speed = Math.hypot(creature.vx, creature.vy);
  if (speed > MAX_SPEED) {
    creature.vx = (creature.vx / speed) * MAX_SPEED;
    creature.vy = (creature.vy / speed) * MAX_SPEED;
  }
  creature.x += creature.vx;
  creature.y += creature.vy;
}

// Slow down. `keep` is the share of speed kept this tick, for example 0.95.
export function glide(creature, keep) {
  creature.vx *= keep;
  creature.vy *= keep;
}

// Turn around at the edges of the water.
export function bounce(creature) {
  if (creature.x < 0 || creature.x > POOL_WIDTH) creature.vx = -creature.vx;
  if (creature.y < SURFACE_Y || creature.y > FLOOR_Y) creature.vy = -creature.vy;
  keepInside(creature);
}

