export function draw(lobster, pen) {
  // lobster faces direction of movement
  if (lobster.vx < 0) pen.flip();
  // body
  pen.fill(BODY);
  pen.ellipse(0, 0, 20, 10);
  // claws
  pen.fill(CLAW);
  pen.poly([-12, 0, -20, -8, -20, 8]);
}

export function update(lobster, world) {
  // keep moving forward, slow a little each tick
  glide(lobster, 0.99);
  step(lobster);
  // turn around when hitting a wall
  bounce(lobster);
}

