class":"rule","key":"text:creatures/:spawn()","kind":"query","new":"f0232ec1533c01b678409f77b8225b75","old":"610def8840aad1627d0ae43f7c23cef6","reason":"no_patch_yet","result":"holds","rule":"X0"}],"kind":"change","ops":[{"content":"// Sea Urchin that waves its spines on the sand
import "../world/bounds.js"

const SPIKE = "#c2a35f" // brownish spines
const BODY = "#e0c68b" // sand color

export function spawn() {
  // positioned on the sand surface
  return { y: FLOOR_Y, angle: 0 }
}

export function update(urchin, world) {
  // make the spines wave back and forth over time
  urchin.angle = Math.sin(world.tick / 20) * 10
}

export function draw(urchin, pen) {
  // draw a simple round body
  pen.fill(BODY)
  pen.ellipse(0, 0, 30, 12)
  // draw spines radiating outward, rotated by current angle
  pen.stroke(SPIKE, 2)
  const count = 12
  for (let i = 0; i < count; i++) {
    const a = (i / count) * Math.PI * 2 + (urchin.angle * Math.PI / 180)
    const x = Math.cos(a) * 15
    const y = Math.sin(a) * 7
    pen.line(0, 0, x, y)
  }
