export function update(squid, world) {
  // Every three seconds, shoot forward and spend a tenth of energy.
  if (world.tick % (3 * TICKS_PER_SECOND) === 0) {
    // Spend energy if possible.
    if (squid.energy > 0) {
      drain(squid, ENERGY_MAX / 10);
      // Give a forward burst.
      squid.vx = 5;
    }
  }
  // Slow down gradually.
  glide(squid, 0.98);
  step(squid);
  wrap(squid);
}

