ds","rule":"L3"},{"cause_seq":null,"class":"rule","key":"world/bounds.js#keepInside","kind":"entity","new":"84aea843c68d82480a596cdba342f04f","old":"84aea843c68d82480a596cdba342f04f","reason":"blind_spot","result":"confirm","rule":"B1"},{"cause_seq":5,"class":"rule","key":"creatures/","kind":"listing","new":"103c7d88789a5c2f3d0da4240d3e3cdc","old":"547978653a42d60791bc5d5e8701cb70","reason":"listing_unused","result":"holds","rule":"L3"},{"cause_seq":6,"class":"rule","key":"world/energy.js#ENERGY_MAX","kind":"entity","new":"f52fdb40e9972b45534f0361ecb65cea","old":"5149f012fe7cd2dfd8820a214ea41ff0","reason":"referenced_entity_changed","result":"repair","rule":"E2"},{"cause_seq":6,"class":"rule","key":"world/energy.js","kind":"file","new":"2304e650a3dcc6560f71104b29fe91e03f154152","old":"e90596b9f7a2619a6bac18cb7ae14663ca814dad","reason":"referenced_entity_changed","result":"repair","rule":"F3"},{"cause_seq":11,"class":"rule","key":"creatures/","kind":"listing","new":"5491fe403454fd67217f0e8ea5b1da40","old":"103c7d88789a5c2f3d0da4240d3e3cdc","reason":"listing_unused","result":"holds","rule":"L3"}],"kind":"change","ops":[{"content":"import { ENERGY_MAX } from "../world/energy.js";
import { step, wander, glide } from "../world/movement.js";
import { keepInside } from "../world/bounds.js";

const SHELL = "tan";
const LEGS = "coral";
const EYE = "black";

// Hide in the shell below this share of full energy.
const HIDE_BELOW = ENERGY_MAX * 0.3;

export function spawn() {
  return { vx: 0.5, vy: 0, energy: ENERGY_MAX };
}

export function update(crab, world) {
  if (crab.energy < HIDE_BELOW) {
    crab.vx = 0;
    crab.vy = 0;
    return;
  }
  wander(crab, 0.4);
  glide(crab, 0.94);
  step(crab);
  keepInside(crab);
}

export function draw(crab, pen) {
  if (crab.energy < HIDE_BELOW) {
    pen.fill(SHELL);
    pen.ellipse(0, 0, 10, 14);
    return;
  }

  if (crab.vx < 0) pen.flip();

  pen.fill(LEGS);
  pen.poly([-6, 8, -14, 16, -4, 12]);
  pen.poly([6, 8, 14, 16, 4, 12]);
  pen.poly([-6, -4, -15, -10, -4, -6]);
  pen.poly([6, -4, 15, -10, 4, -6]);

  pen.fill(SHELL);
  pen.ellipse(0, 0, 18, 12);

  pen.fill(EYE);
  pen.circle(8, -5, 2);
}
